// FetcherWorker — stateless background consumer processing FetchedUrlQueue messages
public class FetcherWorker : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly IHttpClientFactory _httpFactory;
    private readonly ILogger<FetcherWorker> _logger;
    private readonly BlobServiceClient _blobClient;
    private const string RawBlobContainer = "crawler-raw";

    public FetcherWorker(
        IServiceProvider services,
        IHttpClientFactory httpFactory,
        ILogger<FetcherWorker> logger,
        BlobServiceClient blobClient)
    {
        _services = services;
        _httpFactory = httpFactory;
        _logger = logger;
        _blobClient = blobClient;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var scope = _services.CreateScope();
        var queueClient = scope.ServiceProvider.GetRequiredService<QueueClient>();

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                var message = await queueClient.ReceiveMessageAsync(
                    visibilityTimeout: TimeSpan.FromSeconds(30),
                    cancellationToken: stoppingToken);

                if (message == null) continue;

                var fetchUrl = JsonSerializer.Deserialize<FetchUrlMessage>(message.Value.Body);
                var result = await FetchPageAsync(fetchUrl.Url, stoppingToken);

                if (result.Success)
                {
                    var blobPath = string.Format("crawler/raw/{0}.html.gz", result.ContentHash);
                    var blob = _blobClient.GetBlobContainerClient(RawBlobContainer)
                        .GetBlobClient(blobPath);
                    await blob.UploadAsync(
                        new BinaryData(Encoding.UTF8.GetBytes(result.RawHtml)),
                        cancellationToken: stoppingToken);

                    await _eventBus.Publish(new PageFetched
                    {
                        Url = fetchUrl.Url,
                        ContentHash = result.ContentHash,
                        BlobPath = blobPath,
                        ContentType = result.ContentType,
                        StatusCode = result.StatusCode,
                        FetchedAt = DateTime.UtcNow,
                        RequiresJsRender = result.RequiresJsRender,
                        Domain = new Uri(fetchUrl.Url).Host
                    });

                    await queueClient.DeleteMessageAsync(message.Value.MessageId, message.Value.PopReceipt, stoppingToken);
                }
                else
                {
                    fetchUrl.RetryCount++;
                    if (fetchUrl.RetryCount < 3)
                    {
                        await queueClient.SendMessageAsync(
                            JsonSerializer.Serialize(fetchUrl),
                            cancellationToken: stoppingToken);
                    }
                    else
                    {
                        _logger.LogWarning("URL exhausted retries: {Url} (attempts: {Retries})",
                            fetchUrl.Url, fetchUrl.RetryCount);
                        await _eventBus.Publish(new FetchFailed { Url = fetchUrl.Url, Reason = result.Error });
                    }
                    await queueClient.DeleteMessageAsync(message.Value.MessageId, message.Value.PopReceipt, stoppingToken);
                }
            }
            catch (Exception ex) when (!stoppingToken.IsCancellationRequested)
            {
                _logger.LogError(ex, "FetcherWorker error — continuing");
                await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);
            }
        }
    }

    private async Task<FetchResult> FetchPageAsync(string url, CancellationToken ct)
    {
        var client = _httpFactory.CreateClient("crawler");
        client.DefaultRequestHeaders.UserAgent.ParseAdd(
            "InterviewPrepCrawler/1.0 (+https://interviewprep.com/bot)");
        client.DefaultRequestHeaders.Accept.ParseAdd("text/html,application/xhtml+xml");

        try
        {
            using var response = await client.GetAsync(url, ct);
            var content = await response.Content.ReadAsStringAsync(ct);
            var contentHash = ComputeSha256(content);
            var requiresJs = IsLikelySpa(content);

            return new FetchResult
            {
                Success = response.IsSuccessStatusCode,
                StatusCode = (int)response.StatusCode,
                RawHtml = content,
                ContentHash = contentHash,
                ContentType = response.Content.Headers.ContentType?.MediaType ?? "text/html",
                RequiresJsRender = requiresJs,
                Error = response.IsSuccessStatusCode ? null : string.Format("HTTP {0}", (int)response.StatusCode)
            };
        }
        catch (HttpRequestException ex)
        {
            return new FetchResult { Success = false, Error = ex.Message };
        }
        catch (TaskCanceledException)
        {
            return new FetchResult { Success = false, Error = "Timeout" };
        }
    }

    private bool IsLikelySpa(string html)
    {
        var bodyMatch = Regex.Match(html, "<body[^>]*>([\s\S]*?)</body>", RegexOptions.IgnoreCase);
        if (!bodyMatch.Success) return true;
        var scriptCount = Regex.Matches(html, "<script", RegexOptions.IgnoreCase).Count;
        var bodyTextLength = HtmlEntity.DeEntitize(bodyMatch.Groups[1].Value).Trim().Length;
        return scriptCount > 5 && bodyTextLength < 200;
    }

    private string ComputeSha256(string content)
    {
        var bytes = Encoding.UTF8.GetBytes(content);
        var hash = SHA256.HashData(bytes);
        return Convert.ToHexString(hash).ToLowerInvariant();
    }

    private string NormalizeUrl(string url)
    {
        var uri = new Uri(url, UriKind.Absolute);
        var query = HttpUtility.ParseQueryString(uri.Query);
        var strip = new[] { "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "gclid" };
        foreach (var param in strip)
            query.Remove(param);
        var sortedQuery = string.Join("&", query.AllKeys.OrderBy(k => k)
            .Select(k => string.Format("{0}={1}",
                HttpUtility.UrlEncode(k), HttpUtility.UrlEncode(query[k]))));
        var builder = new UriBuilder(uri) { Query = sortedQuery };
        return builder.Uri.AbsoluteUri.TrimEnd('/').ToLowerInvariant();
    }
}

public record FetchResult(bool Success, int StatusCode, string RawHtml, string ContentHash,
    string ContentType, bool RequiresJsRender, string? Error);

public record FetchUrlMessage(string Url, int RetryCount = 0);
